<div class="messages-layout"><section class="admin-panel message-compose"><div class="panel-head"><h3>Message the Foundation Team</h3><span>Your message is delivered to an authorized administrator/support user.</span></div><form method="post" action="<?=url('portal/messages')?>" class="admin-form"><?=csrf_field()?><label class="full"><span>Subject</span><input name="subject" maxlength="180" value="Portal message"></label><label class="full"><span>Message</span><textarea name="body" rows="7" required maxlength="5000" placeholder="Write your message…"></textarea></label><button class="admin-btn full">Send Message →</button></form></section><section class="admin-panel conversation-panel"><div class="panel-head"><h3>Conversation History</h3><span>Latest first</span></div><div class="conversation-stream"><?php foreach($messages as $m):$mine=(int)$m['sender_id']===(int)$user['id'];?><article class="message-bubble <?=$mine?'mine':'theirs'?>"><div><b><?=e($mine?'You':$m['sender_name'])?></b><small><?=e(date('d M Y · g:i A',strtotime($m['created_at'])))?></small></div><?php if($m['subject']):?><strong><?=e($m['subject'])?></strong><?php endif;?><p><?=nl2br(e($m['body']))?></p></article><?php endforeach;?><?php if(!$messages):?><p class="empty">No conversation history yet.</p><?php endif;?></div></section></div>
